WITH metrics AS (SELECT id, order_id, amount, SUM(amount) OVER (PARTITION BY method, status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, LEAD(amount, 1) OVER (PARTITION BY status ORDER BY amount, id) AS next_amount, NTILE(4) OVER (PARTITION BY method ORDER BY amount DESC, id) AS amount_bucket, SUM(amount) OVER (PARTITION BY status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount_2 FROM payments WHERE method IN ('paypal', 'cash', 'card')) SELECT id, order_id, next_amount, amount_bucket, cumulative_amount_2 FROM metrics ORDER BY id, cumulative_amount_2;
